class MultiAccountRoutingMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        target_account = request.headers.get("X-Target-Account-ID")
        request.state.target_account_id = target_account
        return await call_next(request)

app.add_middleware(MultiAccountRoutingMiddleware)

@app.get("/api/v1/billing/stored-cards")
async def list_stored_cards(
    request: Request,
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    account_id = request.state.target_account_id or current_user.default_account_id
    authorized = await db.execute(
        select(AccountMembership).where(
            AccountMembership.account_id == account_id,
            AccountMembership.user_id == current_user.id
        )
    )
    if not authorized.scalar_one_or_none():
        raise HTTPException(status_code=403, detail="Access to target account denied")
    cards = await db.execute(
        select(CreditCardToken).where(CreditCardToken.account_id == account_id)
    )
    return cards.scalars().all()
